--CREATION DATABASE PAYROLL SYSTEM

--USE DATA BASE master
--USE [master]
--GO
---- DROP DATA BASE IF EXISTS
--DROP DATABASE IF EXISTS [PayrollSystem];
--GO
----CREATE DATA BASE
CREATE DATABASE [PayrollSystemDemo];
GO
--USE DATA BASE
USE [PayrollSystemDemo]
GO

--TABLE STATUS
CREATE TABLE [Status](
[IdStatus] INT PRIMARY KEY IDENTITY(1,1) NOT NULL,
[Name] VARCHAR(50) NOT NULL UNIQUE,
[Description] VARCHAR(100) NULL,
[RegistrationDate] DATE DEFAULT GETDATE()
)
GO

--TABLE ROLES
CREATE TABLE [Roles](
[IdRole] INT PRIMARY KEY IDENTITY(1,1) NOT NULL,
[Name] VARCHAR(50) NOT NULL UNIQUE,
[Description] VARCHAR(100) NULL,
[IdStatus] INT REFERENCES [Status](IdStatus),
[RegistrationDate] DATE DEFAULT GETDATE()
)
GO

--TABLE DEPARTMENTS
CREATE TABLE [Departments](
[IdDepartment] INT PRIMARY KEY IDENTITY(1,1) NOT NULL,
[Name] VARCHAR(50) NOT NULL UNIQUE,
[Description] VARCHAR(100) NULL,
[IdStatus] INT REFERENCES [Status](IdStatus),
[RegistrationDate] DATE DEFAULT GETDATE()
)
GO

--TABLE EMPLOYEES
CREATE TABLE [Employees]
(
[IdEmployee] INT PRIMARY KEY IDENTITY(1,1) NOT NULL,
[Name] VARCHAR(50) NOT NULL,
[LastName] VARCHAR(80) NOT NULL,
[Sex] VARCHAR(1) NOT NULL,
[DateBirth] DATE NULL,
[NumberDocument] VARCHAR(11) NOT NULL UNIQUE,
[Address] VARCHAR(250) NOT NULL,
[Phone] VARCHAR(11)	NOT NULL,
[Email] VARCHAR(50) NULL UNIQUE,
[Image] IMAGE NULL,
[DateAdmission] DATE NOT NULL,
[Salary]DECIMAL(18,2) NOT NULL,
[IdDepartment] INT REFERENCES [Departments](IdDepartment),
[IdStatus] INT REFERENCES [Status](IdStatus),
[IdRole] INT REFERENCES [Roles](IdRole),
[RegistrationDate] DATE DEFAULT GETDATE()
);
GO

--TABLE USERS
CREATE TABLE [Users]
(
[IdUser] INT PRIMARY KEY IDENTITY(1,1) NOT NULL,
[UserName] VARCHAR(50) NOT NULL UNIQUE,
[Password] VARCHAR(200) NOT NULL,
[IdEmployee] INT REFERENCES [Employees](IdEmployee),
[IdStatus] INT REFERENCES [Status](IdStatus),
[RegistrationDate] DATE DEFAULT GETDATE()
);
GO

--TABLE PAYROLL
CREATE TABLE [Payroll]
(
[IdPayroll]INT PRIMARY KEY IDENTITY(1,1) NOT NULL,
[IdEmployee] INT REFERENCES [Employees](IdEmployee),
[ExtraHours]DECIMAL(18,2) NOT NULL,
[PriceOvertime]DECIMAL(18,2) NOT NULL,
[OvertimePayments]DECIMAL(18,2) NOT NULL,
[Bonuses]DECIMAL(18,2) NOT NULL,
[FamilyHealthInsurance]DECIMAL(18,2) NOT NULL,
[PensionFundAdministrator]DECIMAL(18,2) NOT NULL,
[IncomeTax]DECIMAL(18,2) NOT NULL,
[SalaryAdvance]DECIMAL(18,2) NOT NULL,
[NetSalary]DECIMAL(18,2) NOT NULL,
[IdStatus] INT REFERENCES [Status](IdStatus),
[RegistrationDate] DATE DEFAULT GETDATE()
);








